/// <summary>
/// PricingAttribute of table <c>MCRCustTable</c> field PostageGroupID.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeMCRCustTablePostageGroupID extends UPSPricingAttributeMCRCustTable implements UPSIPricingAttribute
{
}

