public str getName()
{
    return fieldPName(MCRCustTable, PostageGroupID);
}

public Set getAllowedValues()
{
    var          ret = new Set(Types::String);
    MCRCustTable mCRCustTable;

    while select mCRCustTable
        group by PostageGroupID
    {
        if (! ret.in(mCRCustTable.PostageGroupID))
        {
            ret.add(mCRCustTable.PostageGroupID);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(MCRCustTable, PostageGroupID));
    qbr.value(queryValue(_value));
}
